    run(binary, callback = null) {
        // Load binary into memory at load address
        this.memory.write(uInt32Array.from(binary), 0);

        // Initialize registers
        this.reg.fill(0);
        this.pc = 0x400110; // Entry point

        let instructions = 0;
        const maxInstructions = 1000000;

        while (instructions < maxInstructions) {
            const instr = this.readInstruction(this.pc);

            const advance = this.executeInstruction(instr);

            this.pc += 4;
            if (advance) continue;

            // Check for frame saves
            if (this.frameCount > this.prevFrameCount) {
                if (callback) {
                    callback(this);
                }
                this.prevFrameCount = this.frameCount;
            }

            instructions++;
        }

        console.log(`Executed ${instructions} instructions`);
    }
