    writeU32(a, v) { this.mem.writeUInt32LE(a >>> 0, v >>> 0); }
    readI8(a) { return this.mem.readInt8(a >>> 0); }
    writeI8(a, v) { this.mem.writeInt8(a >>> 0, v & 0xff); }
    readU16(a) { return this.mem.readUInt16LE(a >>> 0); }
    writeU16(a, v) { this.mem.writeUInt16LE(a >>> 0, v & 0xffff); }

