            case 0: // SYS_read
                this.reg[2] = 0;  // Return 0 bytes read
                break;
            case 1: // SYS_write
                if (a0 === 1 || a0 === 2) {  // stdout/stderr
                    const data = this.mem.slice(a1, a1 + a2);
