            this.reg[rt] = this.reg[rs] | (uimm << 16);
            return false;
        }
        if (op === 0x10) {  // XORI
            this.reg[rt] = this.reg[rs] ^ (uimm << 16);
            return false;
        }
        if (op === 0x11) {  // LUI
            this.reg[rt] = uimm << 16;
            return false;
        }

        // Load instructions
        if (op === 0x20) {  // LB
            const addr = (this.reg[rs] + imm) >>> 0;
            this.reg[rt] = this.sign16(this.readI8(addr));
            return false;
        }
        if (op === 0x21) {  // LH
            const addr = (this.reg[rs] + imm) >>> 0;
            this.reg[rt] = this.sign16(this.readU16(addr));
            return false;
        }
        if (op === 0x22) {  // LW
            const addr = (this.reg[rs] + imm) >>> 0;
            this.reg[rt] = this.readU32(addr);
            return false;
        }
        if (op === 0x23) {  // LW (same as above for o32 ABI)
            const addr = (this.reg[rs] + imm) >>> 0;
            this.reg[rt] = this.readU32(addr);
            return false;
        }
        if (op === 0x24) {  // LBU
            const addr = (this.reg[rs] + imm) >>> 0;
            this.reg[rt] = this.readI8(addr) & 0xff;
            return false;
        }
        if (op === 0x25) {  // LHU
            const addr = (this.reg[rs] + imm) >>> 0;
            this.reg[rt] = this.readU16(addr);
            return false;
        }

        // Store instructions
        if (op === 0x28) {  // SB
            const addr = (this.reg[rs] + imm) >>> 0;
            this.writeI8(addr, this.reg[rt]);
            return false;
        }
        if (op === 0x29) {  // SH
            const addr = (this.reg[rs] + imm) >>> 0;
            this.writeU16(addr, this.reg[rt]);
            return false;
        }
        if (op === 0x2a) {  // SW
            const addr = (this.reg[rs] + imm) >>> 0;
            this.writeU32(addr, this.reg[rt]);
            return false;
        }

        // Multiply/Divide
        if (op === 0x32) {  // DIV
            if (this.reg[rt] === 0) {
                this.lo = 0x7fffffff;
                this.hi = 0;
            } else {
                this.lo = Math.floor(this.reg[rs] / this.reg[rt]);
                this.hi = this.reg[rs] % this.reg[rt];
            }
            return false;
        }
        if (op === 0x33) {  // DIVU
            if (this.reg[rt] === 0) {
                this.lo = 0xffffffff;
                this.hi = 0xffffffff;
            } else {
                this.lo = Math.floor(this.reg[rs] / this.reg[rt]);
                this.hi = (this.reg[rs] * this.reg[rt]) >>> 0;
            }
            return false;
        }
        if (op === 0x3c) {  // MFLO
            this.reg[rt] = this.lo;
            return false;
        }

        return false;
    }

    load(binary) {
        const data = fs.readFileSync(binary);
        data.copy(this.mem);
        this.pc = 0x400110;  // Entry point
    }

    run(maxInstructions = 100000) {
        for (let i = 0; i < maxInstructions; i++) {
            const instr = this.readU32(this.pc);
            if (instr === 0) break;

            const advance = this.execute(instr);
            this.pc = (this.pc + 4) >>> 0;
            if (advance) continue;
        }
    }
}

