const fs = require('fs');
const path = require('path');

class MIPS {
    constructor() {
        this.reg = new Uint32Array(32);
        this.pc = 0;
        this.mem = Buffer.alloc(0x8000000, 0);
        this.hi = 0;
        this.lo = 0;
        this.fdTable = new Map();
        this.frameCount = 0;
        this.screenBufAddr = 0x4b0a40;
    }

    sign16(x) { return (x << 16) >> 16; }
    readU32(a) { return this.mem.readUInt32LE(a & 0xffffff); }
    writeU32(a, v) { this.mem.writeUInt32LE(a & 0xffffff, v & 0xffffffff); }
    readI8(a) { return this.mem.readInt8(a & 0xffffff); }
    writeI8(a, v) { this.mem.writeInt8(a & 0xffffff, v & 0xff); }
    readU16(a) { return this.mem.readUInt16LE(a & 0xffffff); }
    writeU16(a, v) { this.mem.writeUInt16LE(a & 0xffffff, v & 0xffff); }

    readString(a) {
        let s = '';
        for (let i = 0; i < 4096; i++) {
            const c = this.mem.readUInt8((a + i) & 0xffffff);
            if (c === 0) break;
            s += String.fromCharCode(c);
        }
        return s;
    }

    syscall() {
        const code = this.reg[2];
        const a0 = this.reg[4];
        const a1 = this.reg[5];
        const a2 = this.reg[6];

        switch (code) {
            case 0: this.reg[2] = 0; break;
            case 1:
                if (a0 === 1 || a0 === 2) {
                    const data = this.mem.slice(a1, a1 + a2);
                    process.stdout.write(data.toString());
                    this.reg[2] = a2;
                } else {
                    this.reg[2] = -1;
                }
                break;
            case 2:
                const fn = this.readString(a1);
                this.reg[2] = this.openFile(fn);
                break;
            case 3:
                this.reg[2] = this.closeFile(a0) ? 0 : -1;
                break;
            case 8: this.reg[2] = a1 >>> 0; break;
            case 74: case 83: case 87: this.reg[2] = 0; break;
            default: this.reg[2] = -1;
        }
    }

    openFile(fn) {
        if (fn.endsWith('.wad')) {
            const fp = path.join('/app', fn);
            if (fs.existsSync(fp)) {
                const data = fs.readFileSync(fp);
                const fd = this.allocFd();
                this.fdTable.set(fd, {type: 'file', data, pos: 0});
                return fd;
            }
        }
        return -1;
    }
    closeFile(fd) { return this.fdTable.delete(fd); }
    allocFd() { for (let i = 0; i < 256; i++) if (!this.fdTable.has(i)) return i; return -1; }

    execute(instr) {
        const op = (instr >>> 26) & 0x3f;
        const rs = (instr >>> 21) & 0x1f;
        const rt = (instr >>> 16) & 0x1f;
        const sa = (instr >>> 6) & 0x1f;
        const imm = (instr << 16) >> 16;

        if (op === 0) {
            const f = instr & 0x3f;
            switch (f) {
                case 0x00: this.reg[rt] = this.reg[rt] >>> sa; break;
                case 0x02: this.reg[rt] = this.reg[rt] >>> sa; break;
                case 0x03: this.reg[rt] = this.reg[rt] >> sa; break;
                case 0x08: this.pc = (this.reg[rs] - 4) >>> 0; return 1;
                case 0x09: this.reg[31] = (this.pc + 4) >>> 0; this.pc = (this.reg[rt] - 4) >>> 0; return 1;
                case 0x20: this.reg[rt] = (this.reg[rs] + this.reg[rt]) | 0; break;
                case 0x21: this.reg[rt] = (this.reg[rs] + this.reg[rt]) >>> 0; break;
                case 0x22: this.reg[rt] = (this.reg[rs] - this.reg[rt]) | 0; break;
                case 0x23: this.reg[rt] = (this.reg[rs] - this.reg[rt]) >>> 0; break;
                case 0x24: this.reg[rt] = this.reg[rs] & this.reg[rt]; break;
                case 0x25: this.reg[rt] = this.reg[rs] | this.reg[rt]; break;
                case 0x26: this.reg[rt] = this.reg[rs] ^ this.reg[rt]; break;
                case 0x27: this.reg[rt] = ~(this.reg[rs] | this.reg[rt]) >>> 0; break;
                case 0x28: this.reg[rt] = ((this.reg[rs] | 0) < (this.reg[rt] | 0)) ? 1 : 0; break;
                case 0x29: this.reg[rt] = (this.reg[rs] < this.reg[rt]) ? 1 : 0; break;
                case 0x0c: this.syscall(); break;
                case 0x42: this.reg[rt] = this.hi; break;
                case 0x43: this.reg[rt] = this.lo; break;
                case 0x44: this.hi = this.reg[rs]; break;
                case 0x45: this.lo = this.reg[rs]; break;
            }
            return false;
        }

        if (op === 0x02) { this.pc = (this.pc + ((instr & 0x03ffffff) << 2) - 4) >>> 0; return 1; }
        if (op === 0x03) { this.reg[31] = (this.pc + 4) >>> 0; this.pc = (this.pc + ((instr & 0x03ffffff) << 2) - 4) >>> 0; return 1; }

        if (op === 0x08) { this.reg[rt] = (this.reg[rs] + imm) >>> 0; return false; }
        if (op === 0x22) { this.reg[rt] = this.readU32((this.reg[rs] + imm) >>> 0); return false; }
        if (op === 0x28) { this.writeU32((this.reg[rs] + imm) >>> 0, this.reg[rt]); return false; }
        if (op === 0x32) { this.lo = Math.floor(this.reg[rs] / this.reg[rt]) >>> 0; this.hi = (this.reg[rs] % this.reg[rt]) >>> 0; return false; }

        return false;
    }

    load(bp) {
        const d = fs.readFileSync(bp);
        d.copy(this.mem);
        this.pc = 0x400110;
    }

    run(max = 100000) {
        for (let i = 0; i < max; i++) {
            const instr = this.readU32(this.pc);
            if (instr === 0) break;
            if (this.execute(instr)) continue;
            this.pc = (this.pc + 4) >>> 0;
        }
    }
}

